# Terraform Refactoring: Dev/Prod to Module with `for_each`

Here's the complete refactored structure with zero-diff state migration.

## Directory Structure

```
.
├── modules/
│   └── app-infrastructure/
│       ├── main.tf
│       ├── variables.tf
│       ├── outputs.tf
│       └── locals.tf
├── main.tf
├── variables.tf
├── outputs.tf
├── dev.tfvars
├── prod.tfvars
├── terraform.tf
└── migrations.sh
```

---

## 1. Module: `modules/app-infrastructure/main.tf`

```hcl
# EKS Cluster
resource "aws_eks_cluster" "this" {
  name            = "${var.environment_name}-cluster"
  role_arn        = aws_iam_role.eks_cluster.arn
  version         = var.kubernetes_version
  vpc_config {
    subnet_ids = var.subnet_ids
  }
  tags = local.common_tags
}

resource "aws_eks_node_group" "this" {
  cluster_name    = aws_eks_cluster.this.name
  node_group_name = "${var.environment_name}-nodes"
  node_role_arn   = aws_iam_role.eks_node.arn
  subnet_ids      = var.subnet_ids
  scaling_config {
    desired_size = var.node_count
    max_size     = var.node_count + 1
    min_size     = var.node_count
  }
  instance_types = [var.node_instance_type]
  tags           = local.common_tags
}

resource "aws_iam_role" "eks_cluster" {
  name = "${var.environment_name}-eks-cluster-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "eks.amazonaws.com"
      }
    }]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role" "eks_node" {
  name = "${var.environment_name}-eks-node-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eks_node_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_node_cni" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

# S3 Bucket
resource "aws_s3_bucket" "assets" {
  bucket = "${var.environment_name}-assets-${data.aws_caller_identity.current.account_id}"
  tags   = local.common_tags
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket                  = aws_s3_bucket.assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count  = var.enable_cross_region_replication ? 1 : 0
  bucket = aws_s3_bucket.assets.id
  role   = aws_iam_role.s3_replication[0].arn

  rule {
    id     = "replicate-to-us-west-2"
    status = "Enabled"
    destination {
      bucket       = aws_s3_bucket.assets_replica[0].arn
      storage_class = "STANDARD_IA"
    }
  }
}

resource "aws_s3_bucket" "assets_replica" {
  count    = var.enable_cross_region_replication ? 1 : 0
  provider = aws.west
  bucket   = "${var.environment_name}-assets-replica-${data.aws_caller_identity.current.account_id}"
  tags     = local.common_tags
}

resource "aws_iam_role" "s3_replication" {
  count = var.enable_cross_region_replication ? 1 : 0
  name  = "${var.environment_name}-s3-replication-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
    }]
  })
}

# RDS PostgreSQL Instance
resource "aws_db_subnet_group" "postgres" {
  name       = "${var.environment_name}-postgres-subnet"
  subnet_ids = var.db_subnet_ids
  tags       = local.common_tags
}

resource "aws_rds_cluster" "postgres" {
  cluster_identifier              = "${var.environment_name}-postgres"
  engine                          = "aurora-postgresql"
  engine_version                  = var.postgres_version
  database_name                   = "appdb"
  master_username                 = "postgres"
  master_password                 = aws_secretsmanager_secret_version.db_password.secret_string
  db_subnet_group_name            = aws_db_subnet_group.postgres.name
  vpc_security_group_ids          = [aws_security_group.rds.id]
  storage_encrypted               = true
  kms_key_id                      = var.kms_key_id
  backup_retention_period         = var.backup_retention_days
  multi_az                        = var.enable_multi_az
  skip_final_snapshot             = false
  final_snapshot_identifier       = "${var.environment_name}-postgres-final-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"
  enabled_cloudwatch_logs_exports = ["postgresql"]
  tags                            = local.common_tags
}

resource "aws_rds_cluster_instance" "postgres" {
  cluster_identifier      = aws_rds_cluster.postgres.id
  instance_class          = var.rds_instance_class
  engine                  = aws_rds_cluster.postgres.engine
  engine_version          = aws_rds_cluster.postgres.engine_version
  publicly_accessible     = false
  monitoring_interval     = 60
  monitoring_role_arn     = aws_iam_role.rds_monitoring.arn
  performance_insights_enabled = true
  tags                    = local.common_tags
}

resource "aws_iam_role" "rds_monitoring" {
  name = "${var.environment_name}-rds-monitoring-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "monitoring.rds.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring_policy" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

resource "aws_security_group" "rds" {
  name   = "${var.environment_name}-rds-sg"
  vpc_id = var.vpc_id
  tags   = local.common_tags
}

resource "aws_security_group_rule" "rds_ingress" {
  type              = "ingress"
  from_port         = 5432
  to_port           = 5432
  protocol          = "tcp"
  cidr_blocks       = var.rds_allowed_cidr_blocks
  security_group_id = aws_security_group.rds.id
}

# Secrets Manager - DB Connection String
resource "aws_secretsmanager_secret" "db_connection" {
  name                    = "${var.environment_name}/db-connection-string"
  recovery_window_in_days = 7
  tags                    = local.common_tags
}

resource "aws_secretsmanager_secret_version" "db_connection" {
  secret_id = aws_secretsmanager_secret.db_connection.id
  secret_string = jsonencode({
    username = "postgres"
    password = random_password.db_password.result
    host     = aws_rds_cluster.postgres.endpoint
    port     = 5432
    engine   = "postgresql"
    dbname   = "appdb"
  })
}

resource "random_password" "db_password" {
  length  = 32
  special = true
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id     = aws_secretsmanager_secret.db_password.id
  secret_string = random_password.db_password.result
}

resource "aws_secretsmanager_secret" "db_password" {
  name = "${var.environment_name}/db-password"
}

# IAM Service Account
resource "aws_iam_user" "service_account" {
  name = "${var.environment_name}-service-account"
  tags = local.common_tags
}

resource "aws_iam_access_key" "service_account" {
  user = aws_iam_user.service_account.name
}

resource "aws_iam_user_policy" "service_account" {
  name   = "${var.environment_name}-service-policy"
  user   = aws_iam_user.service_account.name
  policy = var.enable_cross_region_replication ? data.aws_iam_policy_document.service_prod[0].json : data.aws_iam_policy_document.service_dev[0].json
}

# Dev: restricted policy
data "aws_iam_policy_document" "service_dev" {
  count = var.is_prod ? 0 : 1
  statement {
    actions   = ["s3:GetObject", "s3:PutObject"]
    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }
}

# Prod: least-privilege with OIDC trust
data "aws_iam_policy_document" "service_prod" {
  count = var.is_prod ? 1 : 0
  statement {
    actions   = ["s3:GetObject", "s3:PutObject", "s3:ListBucket"]
    resources = [aws_s3_bucket.assets.arn, "${aws_s3_bucket.assets.arn}/*"]
    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalOrgID"
      values   = [var.organization_id]
    }
  }
}

# HTTPS Exposure: Dev ALB, Prod CloudFront
resource "aws_lb" "dev" {
  count           = var.is_prod ? 0 : 1
  name            = "${var.environment_name}-alb"
  internal        = true
  load_balancer_type = "application"
  subnets         = var.alb_subnet_ids
  tags            = local.common_tags
}

resource "aws_lb_listener" "dev" {
  count           = var.is_prod ? 0 : 1
  load_balancer_arn = aws_lb.dev[0].arn
  port            = 443
  protocol        = "HTTPS"
  ssl_policy      = "ELBSecurityPolicy-TLS-1-2-2017-01"
  certificate_arn = var.alb_certificate_arn
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.dev[0].arn
  }
}

resource "aws_lb_target_group" "dev" {
  count       = var.is_prod ? 0 : 1
  name        = "${var.environment_name}-tg"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = var.vpc_id
  target_type = "ip"
  tags        = local.common_tags
}

resource "aws_cloudfront_distribution" "prod" {
  count = var.is_prod ? 1 : 0
  enabled = true
  comment = "${var.environment_name} assets CDN"
  origin {
    domain_name = aws_s3_bucket.assets.bucket_regional_domain_name
    origin_id   = "s3"
  }
  default_cache_behavior {
    allowed_methods = ["GET", "HEAD"]
    cached_methods  = ["GET", "HEAD"]
    target_origin_id = "s3"
    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }
  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }
  viewer_certificate {
    acm_certificate_arn      = var.cloudfront_certificate_arn
    ssl_support_method       = "sni-only"
    minimum_protocol_version = "TLSv1.2_2021"
  }
  tags = local.common_tags
}
```

