## 2. Module: `modules/app-infrastructure/variables.tf`

```hcl
variable "environment_name" {
  type        = string
  description = "Environment name (dev or prod)"
}

variable "is_prod" {
  type        = bool
  description = "Whether this is production"
  default     = false
}

variable "kubernetes_version" {
  type        = string
  description = "EKS Kubernetes version"
  default     = "1.28"
}

variable "node_count" {
  type        = number
  description = "Number of EKS nodes"
}

variable "node_instance_type" {
  type        = string
  description = "EC2 instance type for EKS nodes"
}

variable "subnet_ids" {
  type        = list(string)
  description = "Subnet IDs for EKS cluster"
}

variable "vpc_id" {
  type        = string
  description = "VPC ID"
}

variable "db_subnet_ids" {
  type        = list(string)
  description = "Subnet IDs for RDS"
}

variable "rds_instance_class" {
  type        = string
  description = "RDS instance class"
}

variable "postgres_version" {
  type        = string
  description = "PostgreSQL version"
  default     = "14.7"
}

variable "enable_multi_az" {
  type        = bool
  description = "Enable Multi-AZ for RDS"
  default     = false
}

variable "backup_retention_days" {
  type        = number
  description = "RDS backup retention in days"
  default     = 7
}

variable "enable_cross_region_replication" {
  type        = bool
  description = "Enable S3 cross-region replication (prod only)"
  default     = false
}

variable "kms_key_id" {
  type        = string
  description = "KMS key ID for encryption"
  default     = ""
}

variable "rds_allowed_cidr_blocks" {
  type        = list(string)
  description = "CIDR blocks allowed to access RDS"
}

variable "alb_subnet_ids" {
  type        = list(string)
  description = "Subnet IDs for ALB (dev only)"
  default     = []
}

variable "alb_certificate_arn" {
  type        = string
  description = "ARN of ACM certificate for ALB (dev only)"
  default     = ""
}

variable "cloudfront_certificate_arn" {
  type        = string
  description = "ARN of ACM certificate for CloudFront (prod only)"
  default     = ""
}

variable "organization_id" {
  type        = string
  description = "AWS Organization ID for OIDC trust (prod only)"
  default     = ""
}

variable "tags" {
  type        = map(string)
  description = "Additional tags"
  default     = {}
}
```

---

## 3. Module: `modules/app-infrastructure/locals.tf`

```hcl
data "aws_caller_identity" "current" {}

locals {
  common_tags = merge(
    {
      Environment = var.environment_name
      Terraform   = "true"
      Module      = "app-infrastructure"
    },
    var.tags
  )
}
```

---

## 4. Module: `modules/app-infrastructure/outputs.tf`

```hcl
output "eks_cluster_endpoint" {
  value = aws_eks_cluster.this.endpoint
}

output "eks_cluster_name" {
  value = aws_eks_cluster.this.name
}

output "s3_bucket_name" {
  value = aws_s3_bucket.assets.id
}

output "rds_endpoint" {
  value = aws_rds_cluster.postgres.endpoint
}

output "db_secret_arn" {
  value = aws_secretsmanager_secret.db_connection.arn
}

output "service_account_access_key" {
  value     = aws_iam_access_key.service_account.id
  sensitive = true
}

output "cloudfront_domain_name" {
  value = try(aws_cloudfront_distribution.prod[0].domain_name, "")
}

output "alb_dns_name" {
  value = try(aws_lb.dev[0].dns_name, "")
}
```

---

## 5. Root: `main.tf`

```hcl
module "environments" {
  for_each = var.environments

  source = "./modules/app-infrastructure"

  environment_name                = each.key
  is_prod                         = each.key == "prod"
  node_count                      = each.value.node_count
  node_instance_type              = each.value.node_instance_type
  subnet_ids                      = each.value.subnet_ids
  vpc_id                          = each.value.vpc_id
  db_subnet_ids                   = each.value.db_subnet_ids
  rds_instance_class              = each.value.rds_instance_class
  enable_multi_az                 = each.key == "prod"
  enable_cross_region_replication = each.key == "prod"
  backup_retention_days           = each.value.backup_retention_days
  rds_allowed_cidr_blocks         = each.value.rds_allowed_cidr_blocks
  alb_subnet_ids                  = each.key == "dev" ? each.value.alb_subnet_ids : []
  alb_certificate_arn             = each.key == "dev" ? each.value.certificate_arn : ""
  cloudfront_certificate_arn      = each.key == "prod" ? each.value.certificate_arn : ""
  organization_id                 = each.key == "prod" ? each.value.organization_id : ""
  kms_key_id                      = each.value.kms_key_id
  tags                            = merge(each.value.tags, { Environment = each.key })
}
```

---

## 6. Root: `variables.tf`

```hcl
variable "environments" {
  type = map(object({
    node_count              = number
    node_instance_type      = string
    subnet_ids              = list(string)
    vpc_id                  = string
    db_subnet_ids           = list(string)
    rds_instance_class      = string
    backup_retention_days   = number
    rds_allowed_cidr_blocks = list(string)
    alb_subnet_ids          = list(string)
    certificate_arn         = string
    organization_id         = optional(string, "")
    kms_key_id              = optional(string, "")
    tags                    = optional(map(string), {})
  }))
  description = "Environment configurations"
}

variable "aws_region" {
  type        = string
  description = "AWS region"
  default     = "us-east-1"
}
```

---

## 7. Root: `outputs.tf`

```hcl
output "environments" {
  value = {
    for env, module_output in module.environments :
    env => {
      eks_cluster_endpoint   = module_output.eks_cluster_endpoint
      eks_cluster_name       = module_output.eks_cluster_name
      s3_bucket_name         = module_output.s3_bucket_name
      rds_endpoint           = module_output.rds_endpoint
      db_secret_arn          = module_output.db_secret_arn
      cloudfront_domain_name = module_output.cloudfront_domain_name
      alb_dns_name           = module_output.alb_dns_name
    }
  }
}
```

